using System.Collections.Generic;
using Unity.Entities;
using UnityEngine;

namespace ToLive.District
{
    /// <summary>
    /// Street positions where citizens live, generated by Tools > To Live and baked into the
    /// District subscene. Every world bakes the same list, so homes cost no bandwidth.
    /// </summary>
    [DisallowMultipleComponent]
    public class CrowdLayoutAuthoring : MonoBehaviour
    {
        public List<Vector3> Homes = new List<Vector3>();
        [Tooltip("Street direction per home (citizens walk along it).")] public List<Vector3> Streets = new List<Vector3>();

        class Baker : Baker<CrowdLayoutAuthoring>
        {
            public override void Bake(CrowdLayoutAuthoring a)
            {
                var e = GetEntity(TransformUsageFlags.None);
                AddComponent<CrowdLayout>(e);
                var homes = AddBuffer<CitizenHome>(e);
                for (var i = 0; i < a.Homes.Count; i++)
                    homes.Add(new CitizenHome { Position = a.Homes[i], Street = i < a.Streets.Count ? (Vector3)a.Streets[i] : Vector3.forward });
            }
        }
    }
}
